12	import { db } from "/opt/nxeon/lib/db.ts";
13	
14	const arg = process.argv[2];
15	if (!arg) {
16	  console.error("Usage: node scripts/recover-errored-server.mjs <hostname|serverId>");
17	  process.exit(1);
18	}
19	
20	const server = await db.server.findFirst({
21	  where: { OR: [{ id: arg }, { hostname: arg }] },
22	  select: { id: true, hostname: true, status: true, vmid: true },
23	});
24	if (!server) {
25	  console.error(`No server matching "${arg}".`);
26	  process.exit(1);
27	}
28	console.log(`Found ${server.hostname} (vmid ${server.vmid}) — status ${server.status}`);
29	
30	if (server.status !== "ERROR") {
31	  console.log(`Not in ERROR (it's ${server.status}). Nothing changed — recovery only applies to an ERROR server.`);
32	  process.exit(0);
33	}
34	
35	await db.server.update({ where: { id: server.id }, data: { status: "STOPPED" } });
36	console.log(`✓ ${server.hostname} set to STOPPED.`);
37	console.log("  Next: in the portal, open this server → Resize/Reinstall → Erase & reinstall.");
38	console.log("  (Grant SDN.Use to the Proxmox role first, or the clone will 403 again.)");
39	process.exit(0);
