37	  'if ! command -v claude >/dev/null 2>&1 && [ ! -x /root/.local/bin/claude ]; then ' +
38	    'if ! command -v node >/dev/null 2>&1; then ' +
39	    "(curl -fsSL https://deb.nodesource.com/setup_20.x | bash - && apt-get install -y nodejs) || " +
40	    "(curl -fsSL https://rpm.nodesource.com/setup_20.x | bash - && dnf install -y nodejs) || " +
41	    "(apt-get install -y nodejs npm || true); fi >/dev/null 2>&1; " +
42	    "npm install -g @anthropic-ai/claude-code >/dev/null 2>&1 || true; fi",
43	  // The native installer lands claude in ~/.local/bin, which isn't on PATH.
44	  // Symlink it to /usr/local/bin (always on PATH) AND add ~/.local/bin to the
45	  // interactive-shell PATH so `claude` works however the customer reaches it.
46	  "mkdir -p /usr/local/bin",
47	  "[ -e /root/.local/bin/claude ] && ln -sf /root/.local/bin/claude /usr/local/bin/claude",
48	  "printf 'export PATH=\"$HOME/.local/bin:$PATH\"\\n' > /etc/profile.d/nxeon-claude-path.sh 2>/dev/null || true",
49	  // Verify by actually RUNNING it — the real proof, not just a file check.
50	  "if /usr/local/bin/claude --version >/dev/null 2>&1 || claude --version >/dev/null 2>&1; then echo NXEON_CLAUDE_OK; else echo NXEON_CLAUDE_FAIL; fi",
51	].join("\n");
52	
53	async function backfillOne(server: any): Promise<boolean> {
54	  const label = `${server.hostname} (vmid ${server.vmid})`;
55	  if (server.status !== "RUNNING") {
56	    console.log(`  [skip] ${label} — status ${server.status}`);
57	    return false;
58	  }
59	  try {
60	    return await withServerSsh(server as SftpServer, async (conn) => {
61	      // Pipe the multi-line script to `bash -s` via stdin — NOT `bash -c "<script>"`,
62	      // whose newlines get mangled when the command is marshalled over SSH.
63	      const run = await execInput(conn, "bash -s", INSTALL, INSTALL_TIMEOUT_MS);
64	      const ok = /NXEON_CLAUDE_OK/.test(run.stdout);
65	      // Independent proof: ask the freshly-symlinked binary for its version.
66	      const ver = await exec(conn, "claude --version 2>&1 | head -n1 || true", QUICK_TIMEOUT_MS);
67	      if (ok) console.log(`  [ ok ] ${label} — claude installed: ${ver.stdout.trim() || "(no version string)"}`);
68	      else console.log(`  [FAIL] ${label} — install did not produce a claude binary`);
69	      return ok;
70	    });
71	  } catch (e: any) {
72	    console.log(`  [ERR ] ${label} — ${e?.message ?? e}`);
73	    return false;
74	  }
75	}
76	
77	async function main() {
78	  const arg = process.argv[2];
79	  if (!arg) {
80	    console.error("Usage: backfill-claude.ts <hostname|vmid> | --all-running");
81	    process.exit(2);
82	  }
83	  let servers: any[];
84	  if (arg === "--all-running") {
85	    servers = await db.server.findMany({ where: { status: "RUNNING" }, select: SELECT });
86	    console.log(`Backfilling Claude Code on ${servers.length} running server(s):`);
87	  } else {
88	    const asVmid = Number(arg);
89	    servers = await db.server.findMany({
90	      where: Number.isInteger(asVmid) ? { vmid: asVmid } : { hostname: arg },
91	      select: SELECT,
92	    });
93	    if (servers.length === 0) {
94	      console.error(`No server found for "${arg}".`);
95	      process.exit(1);
96	    }
97	    console.log(`Backfilling Claude Code on ${servers.length} server(s):`);
98	  }
99	  let ok = 0;
100	  for (const s of servers) if (await backfillOne(s)) ok++;
101	  console.log(`\nDone: ${ok}/${servers.length} now have a working \`claude\`.`);
102	  process.exit(0);
103	}
104	
105	main().catch((e) => {
106	  console.error(e);
107	  process.exit(1);
108	});
