25	/** Loads the row and applies the exact same public/ready gate the page itself
26	 *  uses, so metadata generation and the page body can never disagree about
27	 *  whether this server is visible. */
28	async function loadPublicServer(subdomain: string) {
29	  const row = await db.freeMinecraftServer.findUnique({
30	    where: { subdomain },
31	    select: {
32	      subdomain: true,
33	      name: true,
34	      activeGameType: true,
35	      status: true,
36	      isPublic: true,
37	      publicTagline: true,
38	      publicDescription: true,
39	      containerName: true,
40	    },
41	  });
42	  if (!row || !row.isPublic || row.status !== "READY") return null;
43	  return row;
44	}
