// Shared hostname-uniqueness helpers for every place a `Server` row is
// created (VPS order, game order, NxCloud order, admin-granted free VPS,
// the e2e/seed script). Plain server module (not "use server").
//
// BACKGROUND: `Server.hostname` used to be a plain, unconstrained String.
// Every checkout path that left the field blank silently fell back to the
// exact same literal default ("web-01" for VPS), and nothing checked a
// customer-typed name for collision either — so the live DB ended up with
// several unrelated customers all named "web-01". A hostname-keyed lookup
// (scripts/recover-errored-server.mjs, working a "VPS web-01 stuck in ERROR"
// ticket) then had no way to tell those customers apart and grabbed the
// wrong one's row, surfacing a stranger's SSH port/status while working a
// different customer's ticket (2026-09-24 incident, hsw901013@gmail.com).
// `Server.hostname` is now `@unique` (prisma/schema.prisma) — this module is
// how every writer stays on the right side of that constraint instead of
// crashing checkout on the first collision.
import { db } from "./db";

/** Same character rules every checkout flow already validates against
 *  (lib/order.ts orderSchema, lib/game-order.ts HOSTNAME_RE) — kept here too
 *  so a caller with no format check of its own (e.g. a future script) still
 *  gets one. Keep in sync if either of those changes. */
export const HOSTNAME_RE = /^[a-z0-9]([a-z0-9-]*[a-z0-9])?$/i;
export const HOSTNAME_MAX_LEN = 40;

/**
 * Hostnames that must never be handed to (or typed by) a customer, because a
 * fixed piece of internal infrastructure is looked up BY that literal string
 * with no other scoping — see the dedicated free-Minecraft Docker host row
 * (Server.hostname = "freemc-host"), read by lib/actions-free-minecraft.ts,
 * lib/actions-admin-freemc.ts, lib/actions-freemc-{roles,inventory,worlds,mods}.ts,
 * and the PUBLIC, unauthenticated app/(marketing)/servers/[subdomain]/page.tsx
 * live-status widget — all via `db.server.findFirst({ where: { hostname:
 * "freemc-host" } } )` and then an SSH connection using whatever row's
 * rootPassword that returns. The new `@unique` constraint stops two rows
 * from ever sharing a name at all, but this reservation is what stops a
 * customer from being handed (or choosing) this specific one in the first
 * place — without it, a customer whose own server won that lookup's race
 * would have an anonymous marketing-page visitor's request open a root SSH
 * session against their VM.
 */
export const RESERVED_HOSTNAMES = new Set(["freemc-host"]);

/** Trim + lowercase — the same normalization HostingHostnameClaim's rows use
 *  (normalizeClaimHostname, lib/hosting.ts), so "Web-01" and "web-01" can't
 *  be treated as different names and dodge the unique constraint. */
export function normalizeHostname(raw: string): string {
  return String(raw ?? "").trim().toLowerCase();
}

/** Short base36 suffix — a collision-breaker, not a secret. */
export function randHostnameSuffix(n = 5): string {
  return Math.random().toString(36).slice(2, 2 + n);
}

/** True when a Prisma error is the `Server.hostname` unique-constraint
 *  violation (P2002), as opposed to some other, real failure. */
export function isHostnameConflict(e: unknown): boolean {
  const err = e as { code?: string; meta?: { target?: unknown } } | null | undefined;
  if (err?.code !== "P2002") return false;
  const target = err.meta?.target;
  // Prisma reports the target as either the constraint name or an array of
  // column names, depending on the driver/version — check both shapes.
  if (Array.isArray(target)) return target.includes("hostname");
  return typeof target === "string" && target.includes("hostname");
}

/**
 * Resolve a customer-typed (or blank) hostname candidate into one that's
 * actually free right now, auto-suffixing on collision instead of failing
 * checkout or silently handing out a name someone else already has.
 * `fallbackPrefix` seeds the name when `rawCandidate` is blank — e.g. "web"
 * for a VPS, the game family for a game server.
 *
 * This is an ordinary precheck (`findFirst`), the same idiom
 * isSubdomainAvailable (lib/game-subdomain.ts) uses — good enough to catch
 * the common case (including the entire "everyone left it as web-01" class
 * of bug, which isn't timing-sensitive at all), but NOT itself race-proof
 * against two concurrent checkouts picking the exact same candidate in the
 * same instant. The `Server.hostname` unique constraint is the real,
 * final guard for that: callers must still wrap their `create` in a
 * try/catch and turn a residual `isHostnameConflict` into a clear "please
 * try again" error, exactly like changeGameSubdomain (lib/actions-server.ts)
 * already does for `Server.subdomain`.
 */
export async function resolveUniqueHostname(rawCandidate: string, fallbackPrefix: string): Promise<string> {
  let base = normalizeHostname(rawCandidate);
  if (!base) base = `${fallbackPrefix}-${randHostnameSuffix()}`;
  // Leave room for a "-xxxx" suffix (5 chars) without exceeding the 40-char
  // cap every checkout flow already enforces on the format.
  base = base.slice(0, HOSTNAME_MAX_LEN - 6) || fallbackPrefix.slice(0, HOSTNAME_MAX_LEN - 6);

  let candidate = base;
  for (let attempt = 0; attempt < 6; attempt++) {
    const taken =
      RESERVED_HOSTNAMES.has(candidate) ||
      !!(await db.server.findFirst({ where: { hostname: candidate }, select: { id: true } }));
    if (!taken) return candidate;
    candidate = `${base}-${randHostnameSuffix(4)}`;
  }
  // Last resort after 6 straight collisions (astronomically unlikely) — a
  // millisecond-timestamp tail that cannot repeat within this process.
  return `${base}-${Date.now().toString(36)}`;
}

