  // Prisma reports the target as either the constraint name or an array of
  // column names, depending on the driver/version — check both shapes.
  if (Array.isArray(target)) return target.includes("hostname");
  return typeof target === "string" && target.includes("hostname");
}

/**
 * Resolve a customer-typed (or blank) hostname candidate into one that's
 * actually free right now, auto-suffixing on collision instead of failing
 * checkout or silently handing out a name someone else already has.
 * `fallbackPrefix` seeds the name when `rawCandidate` is blank — e.g. "web"
 * for a VPS, the game family for a game server.
 *
 * This is an ordinary precheck (`findFirst`), the same idiom
 * isSubdomainAvailable (lib/game-subdomain.ts) uses — good enough to catch
 * the common case (including the entire "everyone left it as web-01" class
 * of bug, which isn't timing-sensitive at all), but NOT itself race-proof
 * against two concurrent checkouts picking the exact same candidate in the
 * same instant. The `Server.hostname` unique constraint is the real,
 * final guard for that: callers must still wrap their `create` in a
 * try/catch and turn a residual `isHostnameConflict` into a clear "please
 * try again" error, exactly like changeGameSubdomain (lib/actions-server.ts)
 * already does for `Server.subdomain`.
 */
export async function resolveUniqueHostname(rawCandidate: string, fallbackPrefix: string): Promise<string> {
  let base = normalizeHostname(rawCandidate);
  if (!base) base = `${fallbackPrefix}-${randHostnameSuffix()}`;
  // Leave room for a "-xxxx" suffix (5 chars) without exceeding the 40-char
  // cap every checkout flow already enforces on the format.
  base = base.slice(0, HOSTNAME_MAX_LEN - 6) || fallbackPrefix.slice(0, HOSTNAME_MAX_LEN - 6);

  let candidate = base;
  for (let attempt = 0; attempt < 6; attempt++) {
    const taken =
      RESERVED_HOSTNAMES.has(candidate) ||
      !!(await db.server.findFirst({ where: { hostname: candidate }, select: { id: true } }));
    if (!taken) return candidate;
    candidate = `${base}-${randHostnameSuffix(4)}`;
  }
  // Last resort after 6 straight collisions (astronomically unlikely) — a
  // millisecond-timestamp tail that cannot repeat within this process.
  return `${base}-${Date.now().toString(36)}`;
}

