/**
 * Recover a server stuck in ERROR after a failed reinstall clone (its VM was
 * destroyed but the re-clone failed). Flips ONLY an ERROR server back to STOPPED
 * so the tested reinstall flow in the portal can rebuild it. Does nothing to a
 * server in any other state.
 *
 *   node scripts/recover-errored-server.mjs <hostname|serverId>
 *
 * After this, grant the missing Proxmox privilege (SDN.Use) and re-run the
 * reinstall from the portal — the clone will succeed and the VM is rebuilt.
 *
 * SAFETY (2026-09-24): `hostname` was NOT unique across customers — several
 * unrelated accounts could (and did) share the literal name "web-01". Looking
 * up by hostname with no other scoping and then WRITING to whatever row came
 * back meant this script could silently flip a completely different
 * customer's server, and had already surfaced one customer's SSH port/status
 * while a different customer's ticket was being worked (see
 * lib/hostname.ts's doc comment). `Server.hostname` is now `@unique`
 * (prisma/schema.prisma), so this can only recur for rows created before that
 * constraint was applied — this script still refuses to guess when more than
 * one row matches, and always prints the owning customer's email so whoever
 * runs it can visually confirm it against the ticket BEFORE anything is
 * written.
 */
import { db } from "/opt/nxeon/lib/db.ts";

const arg = process.argv[2];
if (!arg) {
  console.error("Usage: node scripts/recover-errored-server.mjs <hostname|serverId>");
  process.exit(1);
}

const matches = await db.server.findMany({
  where: { OR: [{ id: arg }, { hostname: arg }] },
  select: {
    id: true,
    hostname: true,
    status: true,
    vmid: true,
    createdAt: true,
    user: { select: { email: true } },
  },
  orderBy: { createdAt: "asc" },
});

if (matches.length === 0) {
  console.error(`No server matching "${arg}".`);
  process.exit(1);
}

if (matches.length > 1) {
  console.error(
    `"${arg}" matches ${matches.length} servers — refusing to guess which one you mean.\n` +
      "This can only happen for a hostname created before Server.hostname became unique.\n" +
      "Re-run with the exact server id from the list below:\n",
  );
  for (const m of matches) {
    console.error(`  id=${m.id}  hostname=${m.hostname}  owner=${m.user.email}  status=${m.status}  vmid=${m.vmid}  created=${m.createdAt.toISOString()}`);
  }
  process.exit(1);
}

const server = matches[0];
console.log(`Found ${server.hostname} (vmid ${server.vmid}) — owner ${server.user.email} — status ${server.status}`);
console.log("Confirm this is the customer named in the ticket before continuing.");

if (server.status !== "ERROR") {
  console.log(`Not in ERROR (it's ${server.status}). Nothing changed — recovery only applies to an ERROR server.`);
  process.exit(0);
}

await db.server.update({ where: { id: server.id }, data: { status: "STOPPED" } });
console.log(`✓ ${server.hostname} (owner ${server.user.email}) set to STOPPED.`);
console.log("  Next: in the portal, open this server → Resize/Reinstall → Erase & reinstall.");
console.log("  (Grant SDN.Use to the Proxmox role first, or the clone will 403 again.)");
process.exit(0);

