/**
 * READ-ONLY report of every Server.hostname collision in the live DB, plus any
 * row already sitting on a reserved internal name (lib/hostname.ts
 * RESERVED_HOSTNAMES, e.g. "freemc-host" — the dedicated free-Minecraft
 * Docker host, looked up by that literal string with no other scoping).
 *
 * Run this BEFORE applying the `Server.hostname @unique` schema change
 * (`npx prisma db push`) — the constraint cannot be added while duplicates
 * exist, and it will simply refuse rather than silently drop/rename rows.
 * This script changes nothing; see scripts/dedupe-hostnames.ts for the actual
 * (explicit, reviewable, dry-run-by-default) rename step.
 *
 *   npx tsx scripts/find-duplicate-hostnames.ts
 *
 * Exit code 0 = no duplicates/reserved collisions found (safe to add the
 * constraint right now). Exit code 1 = found some (run the dedupe script
 * first, or resolve manually).
 */
import { db } from "../lib/db";
import { RESERVED_HOSTNAMES } from "../lib/hostname";

async function main() {
  const servers = await db.server.findMany({
    select: { id: true, hostname: true, status: true, vmid: true, createdAt: true, user: { select: { email: true } } },
    orderBy: { createdAt: "asc" },
  });

  const groups = new Map<string, typeof servers>();
  for (const s of servers) {
    const norm = s.hostname.trim().toLowerCase();
    const g = groups.get(norm);
    if (g) g.push(s);
    else groups.set(norm, [s]);
  }

  const dupes = [...groups.entries()].filter(([, rows]) => rows.length > 1);
  const reservedHits = servers.filter((s) => RESERVED_HOSTNAMES.has(s.hostname.trim().toLowerCase()));

  console.log(`Scanned ${servers.length} servers, ${groups.size} distinct (normalized) hostnames.\n`);

  if (dupes.length === 0) {
    console.log("No duplicate hostnames found.");
  } else {
    console.log(`${dupes.length} duplicate hostname group(s):\n`);
    for (const [norm, rows] of dupes) {
      console.log(`  "${norm}" — ${rows.length} servers:`);
      for (const r of rows) {
        console.log(
          `    id=${r.id}  owner=${r.user.email}  status=${r.status}  vmid=${r.vmid ?? "-"}  created=${r.createdAt.toISOString()}` +
            (r.hostname !== norm ? `  (stored as "${r.hostname}")` : ""),
        );
      }
      console.log("");
    }
  }

  if (reservedHits.length > 0) {
    console.log(
      `${reservedHits.length} server(s) already sitting on a RESERVED internal hostname — these collide with a` +
        " fixed infra lookup, not just each other:\n",
    );
    for (const r of reservedHits) {
      console.log(`    id=${r.id}  hostname=${r.hostname}  owner=${r.user.email}  status=${r.status}`);
    }
    console.log("");
  }

  if (dupes.length === 0 && reservedHits.length === 0) {
    console.log("\nSafe to apply the Server.hostname @unique constraint now.");
    process.exit(0);
  }
  console.log("\nRun scripts/dedupe-hostnames.ts (dry run first) before applying the @unique constraint.");
  process.exit(1);
}

main()
  .catch((e) => {
    console.error(e);
    process.exit(2);
  })
  .finally(() => db.$disconnect());

