  for (const s of servers) {
    const norm = s.hostname.trim().toLowerCase();
    const g = groups.get(norm);
    if (g) g.push(s);
    else groups.set(norm, [s]);
  }

  const dupes = [...groups.entries()].filter(([, rows]) => rows.length > 1);

  console.log(`Scanned ${servers.length} servers, ${groups.size} distinct (normalized) hostnames.\n`);

  if (dupes.length === 0) {
    console.log("No duplicate hostnames found. Safe to apply the Server.hostname @unique constraint now.");
    process.exit(0);
  }

  console.log(`${dupes.length} duplicate hostname group(s):\n`);
