    console.log("");
  }

  console.log("Run scripts/dedupe-hostnames.ts (dry run first) before applying the @unique constraint.");
  process.exit(1);
}

main()
  .catch((e) => {
    console.error(e);
    process.exit(2);
  })
  .finally(() => db.$disconnect());

