/**
 * Resolve existing Server.hostname duplicates BEFORE the `@unique` constraint
 * (prisma/schema.prisma) can be applied via `npx prisma db push` — Postgres
 * will refuse to add a unique index while duplicate values exist.
 *
 * Strategy (per normalized-hostname duplicate group): the OLDEST server (by
 * createdAt) keeps its name unchanged; every newer duplicate in the group is
 * renamed to `<name>-<short suffix>`, picking a suffix that collides with
 * neither another existing hostname nor another rename this same run is about
 * to make. Nothing is renamed across groups — only within a group that
 * actually collides.
 *
 * This is a CUSTOMER-VISIBLE change (their server's hostname appears in their
 * dashboard and in DNS/vhost contexts for anyone using a custom domain), so it
 * is a deliberate, explicit, reviewable script — NOT a migration side effect:
 *
 *   npx tsx scripts/dedupe-hostnames.ts             # dry run — prints the plan, changes nothing
 *   npx tsx scripts/dedupe-hostnames.ts --apply      # actually renames, one server.update per row
 *
 * Each rename is logged to AuditLog (action "admin.hostname_dedupe") so it
 * shows up in the admin Activity screen like any other server change.
 *
 * Safe to re-run: a dry run never writes, and --apply re-checks each row's
 * CURRENT hostname immediately before writing (skips it if something else
 * already resolved the collision since the plan was built).
 */
import { db } from "../lib/db";
import { randHostnameSuffix } from "../lib/hostname";

const APPLY = process.argv.includes("--apply");

async function main() {
  const servers = await db.server.findMany({
    select: { id: true, hostname: true, status: true, vmid: true, createdAt: true, user: { select: { email: true } } },
    orderBy: { createdAt: "asc" },
  });

  const allHostnames = new Set(servers.map((s) => s.hostname.trim().toLowerCase()));

  const groups = new Map<string, typeof servers>();
  for (const s of servers) {
    const norm = s.hostname.trim().toLowerCase();
    const g = groups.get(norm);
    if (g) g.push(s);
    else groups.set(norm, [s]);
  }

  const dupeGroups = [...groups.entries()].filter(([, rows]) => rows.length > 1);
  if (dupeGroups.length === 0) {
    console.log("No duplicate hostnames found — nothing to do.");
    process.exit(0);
  }

  type Plan = { id: string; owner: string; from: string; to: string };
  const plan: Plan[] = [];

  for (const [norm, rows] of dupeGroups) {
    // Rows are already createdAt-ascending (the query's orderBy) — keep the
    // first (oldest) untouched, rename every later duplicate.
    const [keeper, ...rest] = rows;
    console.log(`Group "${norm}": keeping ${keeper.id} (owner ${keeper.user.email}, oldest, created ${keeper.createdAt.toISOString()}) unchanged.`);
    for (const dupe of rest) {
      let candidate = "";
      for (let attempt = 0; attempt < 8; attempt++) {
        const c = `${norm}-${randHostnameSuffix(4)}`;
        if (!allHostnames.has(c)) {
          candidate = c;
          break;
        }
      }
      if (!candidate) candidate = `${norm}-${Date.now().toString(36)}`;
      allHostnames.add(candidate); // reserve it so a later dupe in this run can't pick the same one
      plan.push({ id: dupe.id, owner: dupe.user.email, from: dupe.hostname, to: candidate });
    }
  }

  console.log(`\n${APPLY ? "Applying" : "Planned (dry run)"} ${plan.length} rename(s):\n`);
  for (const p of plan) {
    console.log(`  id=${p.id}  owner=${p.owner}  "${p.from}" -> "${p.to}"`);
  }

  if (!APPLY) {
    console.log("\nDry run only — nothing was changed. Re-run with --apply to write these renames.");
    process.exit(0);
  }

  console.log("");
  let done = 0;
  for (const p of plan) {
    // Re-check immediately before writing — cheap insurance against this
    // script running twice concurrently, or a row changing hostname between
    // the plan being built and applied.
    const current = await db.server.findUnique({ where: { id: p.id }, select: { hostname: true } });
    if (!current || current.hostname !== p.from) {
      console.log(`  [skip] ${p.id} — hostname changed since the plan was built (now "${current?.hostname ?? "(deleted)"}").`);
      continue;
    }
    try {
      await db.server.update({ where: { id: p.id }, data: { hostname: p.to } });
      await db.auditLog.create({
        data: {
          userId: null,
          action: "admin.hostname_dedupe",
          detail: `${p.id} (owner ${p.owner}) "${p.from}" -> "${p.to}" — pre-existing duplicate resolved before Server.hostname @unique was applied`,
          category: "server",
        },
      });
      console.log(`  [ ok ] ${p.id} — "${p.from}" -> "${p.to}"`);
      done++;
    } catch (e) {
      console.error(`  [FAIL] ${p.id} — ${(e as Error)?.message ?? e}`);
    }
  }
  console.log(`\nDone: ${done}/${plan.length} renamed.`);
  if (done < plan.length) process.exit(1);
}

main()
  .catch((e) => {
    console.error(e);
    process.exit(2);
  })
  .finally(() => db.$disconnect());

